///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function () {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: "/submission/submit.do?method=registerSubmitInformation&reqObjDocAcpNo=",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_certification
 * @description certification 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_certification = async function () {
    const sbmOptions = {
        id: "tx_fn_certification",
        method: "post",
        action: "/submission/submitCertificate.do",
        ref: "dma_certificationReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_isuSubmit_xhr
 * @description isu Submit xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_isuSubmit_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_isuSubmit_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_isuSubmit_xhr", unresolved: "action:self_submit:tx_fn_isuSubmit_xhr" };
};

/**
 * @method
