/**
 * @method
 * @name certification
 * @description certification 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.certification = async function () {
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const submitTgtIsu = [];
    if (tObj.length === 0) {
        await $c.win.alert('대상 종목을  1종목 까지 선택하셔야 합니다.');
        return;
    } else {
        if (tObj.length > 1) {
            await $c.win.alert('대상 종목을  1종목만  선택하셔야 합니다.');
            return;
        }
    }
    InitCache();
    if (EncFormVerify((document.certiFrm || { elements: [] }))) {
        $c.util.getComponent('step5').src = '/img/submission/step/step_submission_1_5.gif';
        $c.util.getComponent('step6').src = '/img/submission/step/step_submission_1_6_selected.gif';
        (document.certiFrm || { elements: [] }).target = 'certiFrame';
        (document.certiFrm || { elements: [] }).action = "/submission/submitCertificate.do";
        await scwin.tx_fn_certification();
        return;
    } else {
        await $c.win.alert("전송이 취소 되었습니다.");
    }
    return;
};

