/**
 * @method
 * @name moveToList
 * @description move To List 처리
 * @param {*} div div
 * @returns {void}
 * @hidden N
 */
scwin.moveToList = function (div) {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const sObj = $c.util.getComponent('slc_isuCdList').options;
    let iTxt = "", iVal = "";
    for (let i = 0, j = tObj.length; i < sObj.length; i++) {
        if ((sObj[i].selected && div !== 2) || div === 2) {
            iTxt = sObj[i].text;
            iVal = sObj[i].value;
            let isExist = false;
            for (k = 0; k < tObj.length; k++) {
                if (iVal === tObj[k].value) {
                    isExist = true;
                    continue;
                }
            }
            if (!isExist) {
                tObj[j] = new Option(iTxt, iVal);
            }
            j++;
            sObj[i].selected = false;
        }
    }
    scwin.BumpUp($c.util.fieldEl('slc_tgtIsuCdList', 'tgt_isuCd_list'));
};

/**
 * @method
 * @name removeList
 * @description remove List 처리
 * @param {*} div div
 * @returns {void}
 * @hidden N
 */
scwin.removeList = function (div) {
    const Obj = $c.util.getComponent('slc_tgtIsuCdList');
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const len = tObj.length;
    if (div === 1) {
        if (scwin.selectedItem(Obj)) {
            for (let i = 0; i < Obj.options.length; i++) {
                if (Obj.options[i].selected && Obj.options[i] !== "") {
                    Obj.options[i].value = "";
                    Obj.options[i].text = "";
                }
            }
            scwin.BumpUp(Obj);
        }
    } else {
        if (div === 2) {
            for (let i = len - 1; i >= 0; i--) {
                tObj[i].removeNode();
            }
        }
    }
    for (let i = 0; i < tObj.length; i++) {
        tObj[i].selected = false;
    }
};

/**
 * @method
 * @name BumpUp
 * @description Bump Up 처리
 * @param {*} abox abox
 * @returns {void}
 * @hidden N
 */
scwin.BumpUp = function (abox) {
    for (let i = 0; i < abox.options.length; i++) {
        if (abox.options[i].value === "") {
            for (let j = i; j < abox.options.length - 1; j++) {
                abox.options[j].value = abox.options[j + 1].value;
                abox.options[j].text = abox.options[j + 1].text;
            }
            const ln = i;
            break;
        }
    }
    if (ln < abox.options.length) {
        abox.options.length -= 1;
        scwin.BumpUp(abox);
    }
};

/**
 * @method
 * @name selectedItem
 * @description selected Item 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.selectedItem = function (obj) {
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].selected) {
            return true;
        }
    }
    return false;
};
